  ('lm.10-12.skudd.8', 'delf.skudd', '10-12', NULL, 'Etter skudd', 'Omstill raskt til forsvar om motstander får kontroll.', 249),
  ('lm.10-12.heading.1', 'delf.heading', '10-12', NULL, 'Før heading', 'Les ballbanen tidlig for å velge posisjon.', 250),
  ('lm.10-12.heading.2', 'delf.heading', '10-12', NULL, 'Før heading', 'Bruk korte forberedende steg og senk tyngdepunktet for å gjøre klar til å ta sats.', 251),
  ('lm.10-12.heading.3', 'delf.heading', '10-12', NULL, 'Før heading', 'Velg intensjon (klarere, avslutte, legge igjen).', 252),
  ('lm.10-12.heading.4', 'delf.heading', '10-12', NULL, 'Under heading', 'Bruk trestegssats om nødvendig for å hoppe høyt.', 253),
  ('lm.10-12.heading.5', 'delf.heading', '10-12', NULL, 'Under heading', 'Møt ballen på høyeste punkt.', 254),
  ('lm.10-12.heading.6', 'delf.heading', '10-12', NULL, 'Under heading', 'Stuss med toppen av hodet eller styr ballen i ønsket retning med panna.', 255),
  ('lm.10-12.heading.7', 'delf.heading', '10-12', NULL, 'Under heading', 'Bruk hele overkroppen for å få kraft.', 256),
  ('lm.10-12.heading.8', 'delf.heading', '10-12', NULL, 'Etter heading', 'Land kontrollert og forberedt på neste situasjon.', 257),
  ('lm.10-12.heading.9', 'delf.heading', '10-12', NULL, 'Etter heading', 'Vær klar til å vinne andreball eller gå i ny posisjon.', 258),
  ('lm.10-12.press.1', 'delf.press', '10-12', NULL, 'Før press/takling', 'Les situasjonen: se ballførerens retning og lagets balanse. Er laget i ubalanse, prioriter å ikke bli driblet. Er laget i balanse, gå for å vinne ballen.', 259),
  ('lm.10-12.press.2', 'delf.press', '10-12', NULL, 'Før press/takling', 'Velg pressretning (lede innover/utover).', 260),
  ('lm.10-12.press.3', 'delf.press', '10-12', NULL, 'Før press/takling', 'Beregn avstand og tidspunkt for press.', 261),
  ('lm.10-12.press.4', 'delf.press', '10-12', NULL, 'Under press/takling', 'Kombiner sidevendt kroppsstilling med lavt tyngdepunkt.', 262),
  ('lm.10-12.press.5', 'delf.press', '10-12', NULL, 'Under press/takling', 'Bruk armer til balanse og romfølelse uten å lage frispark.', 263),
  ('lm.10-12.press.6', 'delf.press', '10-12', NULL, 'Under press/takling', 'Hold blikket på ballen, ikke på finter.', 264),
  ('lm.10-12.press.7', 'delf.press', '10-12', NULL, 'Under press/takling', 'Takle når ballen er litt for langt fra foten til ballføreren.', 265),
  ('lm.10-12.press.8', 'delf.press', '10-12', NULL, 'Etter press/takling', 'Sikre ballen etter takling (pasning eller føring).', 266),
  ('lm.10-12.press.9', 'delf.press', '10-12', NULL, 'Etter press/takling', 'Reis deg raskt om du faller.', 267),
  ('lm.10-12.press.10', 'delf.press', '10-12', NULL, 'Etter press/takling', 'Finn ny posisjon om ballen spilles videre.', 268),
  ('lm.10-12.klarering.1', 'delf.klarering', '10-12', NULL, 'Før klarering', 'Orienter deg tidlig – vurder hvor ballen havner og hvor du bør stå.', 269),
  ('lm.10-12.klarering.2', 'delf.klarering', '10-12', NULL, 'Før klarering', 'Juster posisjonen og fotarbeidet for god timing.', 270),
  ('lm.10-12.klarering.3', 'delf.klarering', '10-12', NULL, 'Før klarering', 'Bruk armene aktivt for å holde motstandere unna.', 271),
  ('lm.10-12.klarering.4', 'delf.klarering', '10-12', NULL, 'Under klarering', 'Stå skrått i forhold til ballbanen – magen delvis mot motstanderens mål, delvis mot sidelinje.', 272),
  ('lm.10-12.klarering.5', 'delf.klarering', '10-12', NULL, 'Under klarering', 'Bruk foten nærmest ballen, og treff midt på for kraft og høyde.', 273),
  ('lm.10-12.klarering.6', 'delf.klarering', '10-12', NULL, 'Under klarering', 'Prioriter sikkerhet – klarer bort først, så spill.', 274),
  ('lm.10-12.klarering.7', 'delf.klarering', '10-12', NULL, 'Etter klarering', 'Push laget ut.', 275),
  ('lm.10-12.klarering.8', 'delf.klarering', '10-12', NULL, 'Etter klarering', 'Orienter deg og se etter neste situasjon.', 276),
  ('lm.10-12.klarering.9', 'delf.klarering', '10-12', NULL, 'Etter klarering', 'Ta ordet – reorganiser og gi beskjed om posisjoner.', 277),
  ('lm.10-12.kampen-om-ballen.1', 'delf.kampen-om-ballen', '10-12', NULL, 'Før situasjonen', 'Orienter deg tidlig – vurder hvor ballen havner og om du kan nå den først.', 278),
  ('lm.10-12.kampen-om-ballen.2', 'delf.kampen-om-ballen', '10-12', NULL, 'Før situasjonen', 'Juster farten slik at du ankommer situasjonen med balanse.', 279),
  ('lm.10-12.kampen-om-ballen.3', 'delf.kampen-om-ballen', '10-12', NULL, 'Før situasjonen', 'Bruk armene til å holde avstand og stabilitet.', 280),
  ('lm.10-12.kampen-om-ballen.4', 'delf.kampen-om-ballen', '10-12', NULL, 'Under situasjonen', 'Oppretthold tett kontakt – ikke la motstanderen snu opp.', 281),
  ('lm.10-12.kampen-om-ballen.5', 'delf.kampen-om-ballen', '10-12', NULL, 'Under situasjonen', 'Finn riktig balanse – lavt tyngdepunkt, aktiv overkropp.', 282),
  ('lm.10-12.kampen-om-ballen.6', 'delf.kampen-om-ballen', '10-12', NULL, 'Under situasjonen', 'Les motstanderens touch og utnytt det første dårlige touchet.', 283),
  ('lm.10-12.kampen-om-ballen.7', 'delf.kampen-om-ballen', '10-12', NULL, 'Under situasjonen', 'Ta ut rommet mellom ball og motstander.', 284),
  ('lm.10-12.kampen-om-ballen.8', 'delf.kampen-om-ballen', '10-12', NULL, 'Etter situasjonen', 'Reager raskt – enten sikre ballen eller fortsett presset.', 285),
  ('lm.10-12.kampen-om-ballen.9', 'delf.kampen-om-ballen', '10-12', NULL, 'Etter situasjonen', 'Juster posisjon og hjelp laget å samle seg bak ballen.', 286),
  ('lm.10-12.kampen-om-ballen.10', 'delf.kampen-om-ballen', '10-12', NULL, 'Etter situasjonen', 'Kommuniser tydelig – hvem presser, hvem sikrer.', 287),
  ('lm.10-12.spille-framover.ballforer.1', 'tema.spille-framover', '10-12', 'ballforer', 'Før involvering', 'Være spillbar – ut av pasningsskyggen.', 288),
  ('lm.10-12.spille-framover.ballforer.2', 'tema.spille-framover', '10-12', 'ballforer', 'Før involvering', 'Orientert om ledige rom fjernt og nært.', 289),
  ('lm.10-12.spille-framover.ballforer.3', 'tema.spille-framover', '10-12', 'ballforer', 'Før involvering', 'Spillbar gjennom riktig avstand og vinkel til ballfører.', 290),
  ('lm.10-12.spille-framover.ballforer.4', 'tema.spille-framover', '10-12', 'ballforer', 'Før involvering', 'Posisjon og kroppsstilling som gjør at man ser både ballen og motstanders mål.', 291),
  ('lm.10-12.spille-framover.ballforer.5', 'tema.spille-framover', '10-12', 'ballforer', 'Før involvering', 'Riktig kroppsstilling og frekvens i beina ved forflytninger før mottak.', 292),
  ('lm.10-12.spille-framover.ballforer.6', 'tema.spille-framover', '10-12', 'ballforer', 'Under involvering med ball', 'Ro (med ball), åpne (i førstetouch) og true (med blikk og fot).', 293),
  ('lm.10-12.spille-framover.ballforer.7', 'tema.spille-framover', '10-12', 'ballforer', 'Under involvering med ball', 'Utnytte rom fremover i banen ved å føre, drible eller pasning.', 294),
  ('lm.10-12.spille-framover.ballforer.8', 'tema.spille-framover', '10-12', 'ballforer', 'Under involvering med ball', 'Korte hurtige touch med begge føtter for å utnytte rom / skape overtall med føring.', 295),
  ('lm.10-12.spille-framover.ballforer.9', 'tema.spille-framover', '10-12', 'ballforer', 'Under involvering med ball', 'Skape nye rom gjennom pasninger med riktig fart på ball til riktig fot.', 296),
  ('lm.10-12.spille-framover.ballforer.10', 'tema.spille-framover', '10-12', 'ballforer', 'Under involvering med ball', 'Tenke mønstre som «opp – tilbake – igjennom» og «fra trangt – til ledig».', 297),
  ('lm.10-12.spille-framover.ballforer.11', 'tema.spille-framover', '10-12', 'ballforer', 'Under involvering med ball', 'Riktig kroppsstilling og frekvens i beina ved håndtering av ball, føring og dribling.', 298),
  ('lm.10-12.spille-framover.ballforer.12', 'tema.spille-framover', '10-12', 'ballforer', 'Etter involvering', 'Hurtig få ny oversikt etter pasning.', 299),
  ('lm.10-12.spille-framover.ballforer.13', 'tema.spille-framover', '10-12', 'ballforer', 'Etter involvering', 'Ny aksjon umiddelbart for å gjøre seg spillbar og / eller lage rom.', 300),
  ('lm.10-12.spille-framover.ballforer.14', 'tema.spille-framover', '10-12', 'ballforer', 'Etter involvering', 'Være forberedt på å stille om fra angrep til forsvar.', 301),
  ('lm.10-12.spille-framover.laget.1', 'tema.spille-framover', '10-12', 'laget', 'Spillbarhet/bevegelse', 'Bevegelse bak ballfører for å støtte / vende spill.', 302),
  ('lm.10-12.spille-framover.laget.2', 'tema.spille-framover', '10-12', 'laget', 'Spillbarhet/bevegelse', 'Bevegelse forbi upresset ballfører for å skape spillpunkter.', 303),
  ('lm.10-12.spille-framover.laget.3', 'tema.spille-framover', '10-12', 'laget', 'Spillbarhet/bevegelse', 'Bevegelse av spillere foran – true ulike rom samtidig.', 304),
  ('lm.10-12.spille-framover.laget.4', 'tema.spille-framover', '10-12', 'laget', 'Spillbarhet/bevegelse', 'Bevegelse for å skape og utnytte overtall sammen med ballfører.', 305),
  ('lm.10-12.spille-framover.laget.5', 'tema.spille-framover', '10-12', 'laget', 'Spillbarhet/bevegelse', 'True flere rom samtidig med bevegelse og posisjon.', 306),
  ('lm.10-12.spille-framover.laget.6', 'tema.spille-framover', '10-12', 'laget', 'Vinkel/avstand', 'Posisjon og kroppsstilling som gjør at man ser både ballen og motstanders mål.', 307),
  ('lm.10-12.spille-framover.laget.7', 'tema.spille-framover', '10-12', 'laget', 'Vinkel/avstand', 'Gjøre oss store sammen i bredde og dybde.', 308),
  ('lm.10-12.spille-framover.laget.8', 'tema.spille-framover', '10-12', 'laget', 'Vinkel/avstand', 'Gode avstander mellom spillere i ledd og mellom ledd.', 309),
  ('lm.10-12.spille-framover.laget.9', 'tema.spille-framover', '10-12', 'laget', 'Vinkel/avstand', 'Bevegelse bak, forbi og foran ballfører for å skaffe flere pasningsalternativ.', 310),
  ('lm.10-12.spille-framover.laget.10', 'tema.spille-framover', '10-12', 'laget', 'Vinkel/avstand', 'Angripe hurtig fremover. Søke å spille kontrollert inn i (1) bakrom, (2) mellomrom sentralt eller (3) rettvendt i sidekorridor.', 311),
  ('lm.10-12.spille-framover.laget.11', 'tema.spille-framover', '10-12', 'laget', 'Vinkel/avstand', 'Beholde oversikt med ball i beina og kunne ombestemme valg.', 312),
  ('lm.10-12.spille-framover.laget.12', 'tema.spille-framover', '10-12', 'laget', 'Vinkel/avstand', 'Hurtige pasningsvalg eller føre ball i stor fart for å utnytte rom med korte hurtige touch og oversikt.', 313),
  ('lm.10-12.spille-framover.laget.13', 'tema.spille-framover', '10-12', 'laget', 'Vinkel/avstand', 'Utnytte ubalanse gjennom føring i fart, utfordre på, «ta kommandoen».', 314),
  ('lm.10-12.spille-framover.laget.14', 'tema.spille-framover', '10-12', 'laget', 'Vinkel/avstand', 'Oversikt og ballkontroll i små rom / under press for å spille fremover eller vende spill.', 315),
  ('lm.10-12.spille-framover.laget.15', 'tema.spille-framover', '10-12', 'laget', 'Vinkel/avstand', 'Opprettholde eller forsterke ubalanse gjennom temposkifte når vi er i prioritert rom.', 316),
  ('lm.10-12.spille-framover.laget.16', 'tema.spille-framover', '10-12', 'laget', 'Vinkel/avstand', 'Ny aksjon umiddelbart for å gjøre seg spillbar på nytt og / eller skape rom.', 317),
  ('lm.10-12.komme-til-avslutning.ballforer.1', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Komme til avslutning i boks', 'Bevegelser for å komme først på ballen: sprint, stå i ro, «fra – imot», «imot – fra».', 318),
  ('lm.10-12.komme-til-avslutning.ballforer.2', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Komme til avslutning i boks', 'Se med- og motspillere – utnytt rom i forsvarende lag.', 319),
  ('lm.10-12.komme-til-avslutning.ballforer.3', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Komme til avslutning i boks', 'Posisjonere seg på «blindside».', 320),
  ('lm.10-12.komme-til-avslutning.ballforer.4', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Komme til avslutning i boks', 'Pasning igjennom med «vennlig hilsen» (på rett fot til rett tid med rett kraft).', 321),
  ('lm.10-12.komme-til-avslutning.ballforer.5', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Komme til avslutning i boks', 'Korte tette touch for å utfordre, spille eller dra seg forbi. På jakt etter skuddmuligheter.', 322),
  ('lm.10-12.komme-til-avslutning.ballforer.6', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Avslutningen', 'Tålmodig – holde avslutningsrom åpent.', 323),
  ('lm.10-12.komme-til-avslutning.ballforer.7', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Avslutningen', 'Plassering framfor kraft i avslutningen.', 324),
  ('lm.10-12.komme-til-avslutning.ballforer.8', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Avslutningen', 'Kort tid mellom nest siste touch og avslutning.', 325),
  ('lm.10-12.komme-til-avslutning.ballforer.9', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Avslutningen', 'Se på keeper, så på ball.', 326),
  ('lm.10-12.komme-til-avslutning.ballforer.10', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Avslutningen', 'Avslutte hurtig når det er trangt (dårlig sikt for keeper, ball kan skifte retning).', 327),
  ('lm.10-12.komme-til-avslutning.ballforer.11', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Innlegg og «45»: innlegget/siste pasning', 'Oversikt over trusler 1. stolpe, bakre stolpe og «45» og utnytte farligste rom til rett tid.', 328),
  ('lm.10-12.komme-til-avslutning.ballforer.12', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Innlegg og «45»: innlegget/siste pasning', 'Tidlige innlegg – slå på «ryggsiden» av førsteforsvarer.', 329),
  ('lm.10-12.komme-til-avslutning.ballforer.13', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Innlegg og «45»: innlegget/siste pasning', 'Slå innlegg i rom som angripes (ofte forbi første forsvarsspiller i boks).', 330),
  ('lm.10-12.komme-til-avslutning.ballforer.14', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Innlegg og «45»: innlegget/siste pasning', 'Beholde oversikt med ball i beina, finne rett timing og kunne kamuflere valg.', 331),
  ('lm.10-12.komme-til-avslutning.ballforer.15', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Innlegg og «45»: avslutningen', 'Først på ball!', 332),
  ('lm.10-12.komme-til-avslutning.ballforer.16', 'tema.komme-til-avslutning', '10-12', 'ballforer', 'Innlegg og «45»: avslutningen', 'Skudd/heading tilbake i det hjørnet ballen kom fra er ofte lurt.', 333),
  ('lm.10-12.komme-til-avslutning.laget.1', 'tema.komme-til-avslutning', '10-12', 'laget', 'Bevegelse – lage/utnytte rom', 'Trusler inn i bakrom.', 334),
  ('lm.10-12.komme-til-avslutning.laget.2', 'tema.komme-til-avslutning', '10-12', 'laget', 'Bevegelse – lage/utnytte rom', 'Søke å spille igjennom før rundt.', 335),
  ('lm.10-12.komme-til-avslutning.laget.3', 'tema.komme-til-avslutning', '10-12', 'laget', 'Bevegelse – lage/utnytte rom', 'Samtidige, truende og eksplosive bevegelser.', 336),
  ('lm.10-12.komme-til-avslutning.laget.4', 'tema.komme-til-avslutning', '10-12', 'laget', 'Bevegelse – lage/utnytte rom', 'Benytte veggspill og kombinasjoner for å spille seg igjennom.', 337),
  ('lm.10-12.komme-til-avslutning.laget.5', 'tema.komme-til-avslutning', '10-12', 'laget', 'Bevegelse – lage/utnytte rom', 'Riktig kroppsstilling og frekvens i beina i utgangsposisjoner og ved forflytninger.', 338),
  ('lm.10-12.komme-til-avslutning.laget.6', 'tema.komme-til-avslutning', '10-12', 'laget', 'Komme til avslutning i boks', 'Bevegelser for å komme først på ballen: sprint, stå i ro, «fra – imot», «imot – fra».', 339),
  ('lm.10-12.komme-til-avslutning.laget.7', 'tema.komme-til-avslutning', '10-12', 'laget', 'Komme til avslutning i boks', 'Se med- og motspillere – utnytt rom i forsvarende lag.', 340),
  ('lm.10-12.komme-til-avslutning.laget.8', 'tema.komme-til-avslutning', '10-12', 'laget', 'Komme til avslutning i boks', 'Posisjonere seg på «blindside».', 341),
  ('lm.10-12.komme-til-avslutning.laget.9', 'tema.komme-til-avslutning', '10-12', 'laget', 'Innlegg og «45»: spillbarhet/bevegelse', 'Samtidige, truende og eksplosive bevegelser. True ulike rom.', 342),
  ('lm.10-12.komme-til-avslutning.laget.10', 'tema.komme-til-avslutning', '10-12', 'laget', 'Innlegg og «45»: spillbarhet/bevegelse', 'True 1. stolpe, bakre stolpe og «45».', 343),
  ('lm.10-12.komme-til-avslutning.laget.11', 'tema.komme-til-avslutning', '10-12', 'laget', 'Innlegg og «45»: spillbarhet/bevegelse', 'Timing = lese ballførers blikk og touch.', 344),
  ('lm.10-12.komme-til-avslutning.laget.12', 'tema.komme-til-avslutning', '10-12', 'laget', 'Innlegg og «45»: spillbarhet/bevegelse', 'Flest mulig trusler innenfor stengene.', 345),
  ('lm.10-12.komme-til-avslutning.laget.13', 'tema.komme-til-avslutning', '10-12', 'laget', 'Innlegg og «45»: spillbarhet/bevegelse', 'Tålmodig – holde avslutningsrom åpent.', 346),
  ('lm.10-12.komme-til-avslutning.laget.14', 'tema.komme-til-avslutning', '10-12', 'laget', 'Innlegg og «45»: spillbarhet/bevegelse', 'Plassere seg i blindsiden til motstander.', 347),
  ('lm.10-12.vinne-ball.1f.1', 'tema.vinne-ball', '10-12', '1f', 'Før involvering', 'Oversikt over ball, med- og motspillere.', 348),
  ('lm.10-12.vinne-ball.1f.2', 'tema.vinne-ball', '10-12', '1f', 'Før involvering', 'Vurdere om vi er «i press» eller «kontrollerer rom».', 349),
  ('lm.10-12.vinne-ball.1f.3', 'tema.vinne-ball', '10-12', '1f', 'Før involvering', 'Velge pressøyeblikk ut ifra avstand, motstanders kroppsposisjon, blikk, fot og touch.', 350),
  ('lm.10-12.vinne-ball.1f.4', 'tema.vinne-ball', '10-12', '1f', 'Før involvering', 'Kroppskontroll – kontroll på overkroppen i utgangsposisjoner for raskt å kunne gå i alle retninger.', 351),
  ('lm.10-12.vinne-ball.1f.5', 'tema.vinne-ball', '10-12', '1f', 'Under involvering', 'Komme tett i press med rett fart og opprettholde presset med riktig kroppsstilling og høy frekvens i beina.', 352),
  ('lm.10-12.vinne-ball.1f.6', 'tema.vinne-ball', '10-12', '1f', 'Under involvering', 'Bevisst på rom rundt seg for å stenge avspillpunkter.', 353),
  ('lm.10-12.vinne-ball.1f.7', 'tema.vinne-ball', '10-12', '1f', 'Under involvering', 'Kroppskontroll og fart i beina – kontroll på overkroppen ved forflytninger. Aktiv armbruk ved duellspill og kroppskontakt.', 354),
  ('lm.10-12.vinne-ball.1f.8', 'tema.vinne-ball', '10-12', '1f', 'Under involvering', 'Tett i ballfører for å vinne ball eller tvinge frem en upresis pasning.', 355),
  ('lm.10-12.vinne-ball.1f.9', 'tema.vinne-ball', '10-12', '1f', 'Under involvering', 'Utnytte dårlige, lange og for mange touch.', 356),
  ('lm.10-12.vinne-ball.1f.10', 'tema.vinne-ball', '10-12', '1f', 'Etter involvering', 'Skaffe seg oversikt på nytt, er du fortsatt 1F?', 357),
  ('lm.10-12.vinne-ball.1f.11', 'tema.vinne-ball', '10-12', '1f', 'Etter involvering', 'Presse på nytt om mulig.', 358),
  ('lm.10-12.vinne-ball.1f.12', 'tema.vinne-ball', '10-12', '1f', 'Etter involvering', 'Raskt på «rett side» av ball når pressejobben er over.', 359),
  ('lm.10-12.vinne-ball.laget.1', 'tema.vinne-ball', '10-12', 'laget', 'Forflytning', 'Posisjonering i forhold til ball og medspillere, ikke motspillere – soneforsvar.', 360),
  ('lm.10-12.vinne-ball.laget.2', 'tema.vinne-ball', '10-12', 'laget', 'Forflytning', 'Ved balltap: gjenvinning eller fortest mulig få flest mulig på rett side av ball.', 361),
  ('lm.10-12.vinne-ball.laget.3', 'tema.vinne-ball', '10-12', 'laget', 'Forflytning', 'Reagere hurtig og samlet på definerte pressignaler som støttepasning, dårlig touch, feilvendte spillere, ball til back.', 362),
  ('lm.10-12.vinne-ball.laget.4', 'tema.vinne-ball', '10-12', 'laget', 'Forflytning', 'Kontinuerlig justering av høyde i forhold til ballfører, lese fot, blikk, kroppsposisjon og trusler.', 363),
  ('lm.10-12.vinne-ball.laget.5', 'tema.vinne-ball', '10-12', 'laget', 'Forflytning', 'Senke oss samlet og ha kontroll på farlige rom dersom vi mister ball / ikke har press på ballføreren.', 364),
  ('lm.10-12.vinne-ball.laget.6', 'tema.vinne-ball', '10-12', 'laget', 'Avstand', 'Hurtig komme til definerte utgangsposisjoner, med rett kroppsstilling for å ha kontroll på rom og klare for å presse.', 365),
  ('lm.10-12.vinne-ball.laget.7', 'tema.vinne-ball', '10-12', 'laget', 'Avstand', 'Korte avstander mellom spillere i lengden og bredden.', 366),
  ('lm.10-12.vinne-ball.laget.8', 'tema.vinne-ball', '10-12', 'laget', 'Avstand', 'Jo tettere press, jo kortere avstander.', 367),
  ('lm.10-12.vinne-ball.laget.9', 'tema.vinne-ball', '10-12', 'laget', 'Avstand', 'Pressansvar for spillere foran oss i hver vår sone når vi presser høyt.', 368),
  ('lm.10-12.hindre-avslutning.1f.1', 'tema.hindre-avslutning', '10-12', '1f', 'Hindre avslutning', 'Komme tett og presse – se på ball.', 369),
  ('lm.10-12.hindre-avslutning.1f.2', 'tema.hindre-avslutning', '10-12', '1f', 'Hindre avslutning', 'Kontroll på overkropp og alltid en fot i bakken – korte ned stegene inn i press.', 370),
  ('lm.10-12.hindre-avslutning.1f.3', 'tema.hindre-avslutning', '10-12', '1f', 'Hindre avslutning', 'Stresse ballfører; forsøke å vinne ball, oppholde og / eller lede vekk fra mål.', 371),
  ('lm.10-12.hindre-avslutning.1f.4', 'tema.hindre-avslutning', '10-12', '1f', 'Hindre avslutning', 'Ta rommet mellom ballfører og ball før man tar ball.', 372),
  ('lm.10-12.hindre-avslutning.1f.5', 'tema.hindre-avslutning', '10-12', '1f', 'Hindre avslutning', 'Hold feilvendte spillere feilvendt – armlengdes avstand.', 373),
  ('lm.10-12.hindre-avslutning.1f.6', 'tema.hindre-avslutning', '10-12', '1f', 'Håndtere avslutning', 'Keeper er posisjonert og er skuddklar.', 374),
  ('lm.10-12.hindre-avslutning.1f.7', 'tema.hindre-avslutning', '10-12', '1f', 'Håndtere avslutning', 'Opp i blokk, blokke med fremsiden av kroppen.', 375),
  ('lm.10-12.hindre-avslutning.1f.8', 'tema.hindre-avslutning', '10-12', '1f', 'Håndtere avslutning', 'Stenge av ett hjørne – keeper tar det andre (aldri skudd mellom beina).', 376),
  ('lm.10-12.hindre-avslutning.1f.9', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: posisjonering/press – nekte rom', 'Blokkere eller hindre innlegg/pasning.', 377),
  ('lm.10-12.hindre-avslutning.1f.10', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: posisjonering/press – nekte rom', 'Tvinge eventuelt innlegg foran spiller i press.', 378),
  ('lm.10-12.hindre-avslutning.1f.11', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: posisjonering/press – nekte rom', 'Sidestilt kroppsstilling så man ser ball og motstandere.', 379),
  ('lm.10-12.hindre-avslutning.1f.12', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: posisjonering/press – nekte rom', 'Hurtig i posisjon mellom eget mål og motstander.', 380),
  ('lm.10-12.hindre-avslutning.1f.13', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: posisjonering/press – nekte rom', 'Ta kontroll foran eget mål gjennom posisjonering innenfor stolpene.', 381),
  ('lm.10-12.hindre-avslutning.1f.14', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: posisjonering/press – nekte rom', 'Spillere på feil side skal komme seg på rett side.', 382),
  ('lm.10-12.hindre-avslutning.1f.15', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: hindre avslutning', 'Oversikt over trusler mot 1. stolpe, bakre stolpe og «45» og kontroll på farligste rom.', 383),
  ('lm.10-12.hindre-avslutning.1f.16', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: hindre avslutning', 'Posisjon mellom motstander og mål.', 384),
  ('lm.10-12.hindre-avslutning.1f.17', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: hindre avslutning', 'Offervilje – først på ball.', 385),
  ('lm.10-12.hindre-avslutning.1f.18', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: hindre avslutning', '«Ta duellen før duellen» – gå i kropp for å ta bort timing og fart hos motspiller.', 386),
  ('lm.10-12.hindre-avslutning.1f.19', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: håndtere avslutning', 'Tverrvende og inn i press på nytt bakfra hvis mulig.', 387),
  ('lm.10-12.hindre-avslutning.1f.20', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: håndtere avslutning', '«På plass» igjen når pressejobben er ferdig.', 388),
  ('lm.10-12.hindre-avslutning.1f.21', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: håndtere avslutning', 'Komme på rett side igjen hvis man er passert og utenfor presseavstand.', 389),
  ('lm.10-12.hindre-avslutning.1f.22', 'tema.hindre-avslutning', '10-12', '1f', 'Innlegg og «45»: håndtere avslutning', 'Være mentalt forberedt på å omstille fra forsvar til angrep.', 390),
  ('lm.10-12.hindre-avslutning.laget.1', 'tema.hindre-avslutning', '10-12', 'laget', 'Hindre avslutning', 'Sidestilt kroppsstilling så man ser ball og motstandere.', 391),
  ('lm.10-12.hindre-avslutning.laget.2', 'tema.hindre-avslutning', '10-12', 'laget', 'Hindre avslutning', 'Hurtig i posisjon mellom eget mål og motstander.', 392),
  ('lm.10-12.hindre-avslutning.laget.3', 'tema.hindre-avslutning', '10-12', 'laget', 'Hindre avslutning', 'Ta kontroll foran eget mål gjennom posisjonering innenfor stolpene.', 393),
  ('lm.10-12.hindre-avslutning.laget.4', 'tema.hindre-avslutning', '10-12', 'laget', 'Hindre avslutning', 'Spillere på feil side skal komme seg på rett side.', 394),
  ('lm.10-12.hindre-avslutning.laget.5', 'tema.hindre-avslutning', '10-12', 'laget', 'Hindre avslutning', 'Hold feilvendte spillere feilvendt – armlengdes avstand.', 395),
  ('lm.10-12.hindre-avslutning.laget.6', 'tema.hindre-avslutning', '10-12', 'laget', 'Håndtere avslutning', 'Keeper er posisjonert og er skuddklar.', 396),
  ('lm.10-12.hindre-avslutning.laget.7', 'tema.hindre-avslutning', '10-12', 'laget', 'Håndtere avslutning', 'Opp i blokk, blokke med fremsiden av kroppen.', 397),
  ('lm.10-12.hindre-avslutning.laget.8', 'tema.hindre-avslutning', '10-12', 'laget', 'Håndtere avslutning', 'Stenge av ett hjørne – keeper tar det andre (aldri skudd mellom beina).', 398),
  ('lm.10-12.hindre-avslutning.laget.9', 'tema.hindre-avslutning', '10-12', 'laget', 'Håndtere avslutning', 'Alle i «beredskap» frem til ballen er ute av boksen.', 399),
  ('lm.10-12.hindre-avslutning.laget.10', 'tema.hindre-avslutning', '10-12', 'laget', 'Håndtere avslutning', 'Spillere som ikke har markering/blokker – beskytt målet.', 400),
  ('lm.10-12.hindre-avslutning.laget.11', 'tema.hindre-avslutning', '10-12', 'laget', 'Innlegg og «45»: hindre avslutning', 'Blokkere eller hindre innlegg/pasning.', 401),
  ('lm.10-12.hindre-avslutning.laget.12', 'tema.hindre-avslutning', '10-12', 'laget', 'Innlegg og «45»: hindre avslutning', 'Oversikt over trusler mot 1. stolpe, bakre stolpe og «45» og kontroll på farligste rom.', 402),
  ('lm.10-12.hindre-avslutning.laget.13', 'tema.hindre-avslutning', '10-12', 'laget', 'Innlegg og «45»: hindre avslutning', 'Offervilje – først på ball.', 403),
  ('lm.10-12.hindre-avslutning.laget.14', 'tema.hindre-avslutning', '10-12', 'laget', 'Innlegg og «45»: hindre avslutning', '«Ta duellen før duellen» – gå i kropp for å ta bort timing og fart hos motspiller.', 404),
  ('lm.10-12.hindre-avslutning.laget.15', 'tema.hindre-avslutning', '10-12', 'laget', 'Innlegg og «45»: hindre avslutning', 'Markere og ha kontroll på farlige rom helt til situasjonen er avklart. Når motstander ikke når ball, ta dem likevel ut for å skaffe rom til keeper.', 405);
