-- NFF-katalogen i databasen: hovedtema, delferdigheter og læringsmomenter.
--
-- Til nå lå katalogen bare i koden (lib/nff/fagplan.ts). Her blir den tabeller,
-- så trenerne på sikt kan velge fra nedtrekk (årshjul, treningsopplegg, KI) og
-- legge til egne punkter, for eksempel omstilling.
--
-- * NFF-radene (spond_group_id IS NULL) er felles for alle lag og fylles inn
--   her fra fagplan.ts, med de samme ID-ene som øvelsene allerede er tagget
--   med (tema.*, delf.*, lm.*). En enhetstest sjekker at de stemmer med koden.
-- * Egne rader hører til én hovedgruppe (lag) og har source = 'egen'.
-- * Å slette betyr å skjule for laget (nff_hidden), både for NFF-rader og
--   egne rader. Da mister ikke øvelser og årshjul teksten de viser til.
--
-- Årshjulet får hovedtema og læringsmomenter (fra både hovedtema og
-- delferdigheter) ved siden av fritekstfeltene, som appen fortsatt bruker.

CREATE TABLE nff_topics (
  id             text PRIMARY KEY CHECK (id ~ '^(tema|delf)\.[a-z0-9.-]{1,60}$'),
  kind           text NOT NULL CHECK (kind IN ('hovedtema', 'delferdighet')),
  label          text NOT NULL CHECK (length(btrim(label)) BETWEEN 1 AND 120),
  side           text NOT NULL CHECK (side IN ('angrep', 'forsvar', 'omstilling')),
  bands          text[] NOT NULL CHECK (cardinality(bands) BETWEEN 1 AND 10 AND array_to_string(bands, ',') ~ '^[0-9]{1,2}-[0-9]{1,2}(,[0-9]{1,2}-[0-9]{1,2})*$'),
  source         text NOT NULL DEFAULT 'nff' CHECK (source IN ('nff', 'egen')),
  spond_group_id text,
  sort           integer NOT NULL DEFAULT 0,
  created_by     text,
  created_at     timestamptz NOT NULL DEFAULT now(),
  CHECK ((source = 'nff') = (spond_group_id IS NULL)),
  CHECK (left(id, 5) = CASE kind WHEN 'hovedtema' THEN 'tema.' ELSE 'delf.' END)
);

CREATE INDEX nff_topics_group_idx ON nff_topics (spond_group_id);

CREATE TABLE nff_learning_points (
  id             text PRIMARY KEY CHECK (id ~ '^lm\.[a-z0-9.-]{1,80}$'),
  topic_id       text NOT NULL REFERENCES nff_topics (id),
  band           text NOT NULL CHECK (band ~ '^[0-9]{1,2}-[0-9]{1,2}$'),
  -- For hovedtema: ballforer, laget eller 1f. Delferdigheter har ingen rolle.
  role           text CHECK (role IN ('ballforer', 'laget', '1f')),
  -- NFFs underoverskrift, f.eks. «Før medtak/mottak» eller «Spillbarhet/bevegelse».
  phase          text NOT NULL DEFAULT '' CHECK (length(phase) <= 80),
  text           text NOT NULL CHECK (length(btrim(text)) BETWEEN 1 AND 300),
  source         text NOT NULL DEFAULT 'nff' CHECK (source IN ('nff', 'egen')),
  spond_group_id text,
  sort           integer NOT NULL DEFAULT 0,
  created_by     text,
  created_at     timestamptz NOT NULL DEFAULT now(),
  CHECK ((source = 'nff') = (spond_group_id IS NULL))
);

CREATE INDEX nff_learning_points_topic_idx ON nff_learning_points (topic_id, band);
CREATE INDEX nff_learning_points_group_idx ON nff_learning_points (spond_group_id);

-- Hva et lag har skjult (slettet) fra katalogen: et hovedtema, en delferdighet eller et læringsmoment.
CREATE TABLE nff_hidden (
  spond_group_id text NOT NULL,
  item_id        text NOT NULL CHECK (item_id ~ '^(tema|delf|lm)\.'),
  hidden_by      text NOT NULL,
  hidden_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (spond_group_id, item_id)
);

ALTER TABLE nff_topics ENABLE ROW LEVEL SECURITY;
ALTER TABLE nff_learning_points ENABLE ROW LEVEL SECURITY;
ALTER TABLE nff_hidden ENABLE ROW LEVEL SECURITY;
CREATE POLICY nymark_app_all ON nff_topics TO nymark_app USING (true) WITH CHECK (true);
CREATE POLICY nymark_app_all ON nff_learning_points TO nymark_app USING (true) WITH CHECK (true);
CREATE POLICY nymark_app_all ON nff_hidden TO nymark_app USING (true) WITH CHECK (true);

-- Årshjulet: hovedtema og 1–2 læringsmomenter per måned, ved siden av fritekst.
ALTER TABLE season_themes ADD COLUMN hovedtema_id text REFERENCES nff_topics (id);
ALTER TABLE season_themes ADD COLUMN learning_point_ids text[] NOT NULL DEFAULT '{}' CHECK (cardinality(learning_point_ids) <= 2);

-- NFFs fagplaner (Planverk 2026 på tiim.no), generert fra lib/nff/fagplan.ts.


